(function () {
  app.modals.SelectUsersModal = function () {
    var _modalManager;
    var _leaveRequestService = abp.services.app.leaveRequest;
    var _organizationService = abp.services.app.organization;
    var _$table;
    var _$filterInput;
    var dataTable;
    var selectedUsers = []; // Lưu trữ tất cả user đã chọn
    var initialSelectedIds = []; // ID đã được chọn ban đầu
    var organizationUnitId = null;

    function getFilter() {
      return {
        filter: $('#Filter').val(),
        organizationUnitId: organizationUnitId,
      };
    }

    function refreshTable() {
      dataTable.ajax.reload();
    }

    function updateSaveButtonState() {
      var $saveButton = _modalManager.getModal().find('#btnAddUsersToLeaveRequest');
      $saveButton.prop('disabled', selectedUsers.length === 0);
    }

    this.init = function (modalManager) {
      _modalManager = modalManager;
      const args = _modalManager.getArgs();

      organizationUnitId = args.organizationUnitId;

      initialSelectedIds = Array.isArray(args) ? [...args] :
        (args._selectedUserIds ? [...args._selectedUserIds] : []);

      _$table = $('#addUserModalTable');
      _$filterInput = _modalManager.getModal().find('#Filter');

      dataTable = _$table.DataTable({
        paging: true,
        serverSide: true,
        processing: true,
        info: true,
        destroy: true,
        listAction: {
          ajaxFunction: _organizationService.getAllUsersByOrganizationUnitId,
          inputFilter: getFilter
        },
        order: [[1, 'asc']],
        columns: [
          {
            data: null,
            orderable: false,
            render: function (data) {
              const isChecked = selectedUsers.some(u => u.userId === data.id);
              return `
                                <label class="checkbox form-check">
                                    <input type="checkbox" 
                                           class="form-check-input user-checkbox" 
                                           data-user-id="${data.id}" 
                                           ${isChecked ? 'checked' : ''}>
                                    <span class="form-check-label"></span>
                                </label>`;
            }
          },
          { data: 'name', title: app.localize('NameEmployee') },
          { data: 'emailAddress', title: app.localize('Email') },
          { data: 'id', visible: false }
        ],
        createdRow: function (row, data) {
          $(row).attr('data-id', data.id);

          // Nếu là lần đầu mở modal
          if (initialSelectedIds.includes(data.id) &&
            !selectedUsers.some(u => u.userId === data.id)) {
            selectedUsers.push({
              userId: data.id,
              userName: data.name,
              emailAddress: data.emailAddress
            });
            $(row).find('.user-checkbox').prop('checked', true);
          }
        },
        drawCallback: function () {
          $('.user-checkbox').each(function () {
            const userId = $(this).data('user-id');
            $(this).prop('checked', selectedUsers.some(u => u.userId === userId));
          });
          updateSaveButtonState();
        }
      });

      // Xử lý click checkbox
      _$table.on('change', '.user-checkbox', function () {
        const userId = $(this).data('user-id');
        const row = dataTable.row($(this).closest('tr'));
        const userData = row.data();

        if ($(this).is(':checked')) {
          if (!selectedUsers.some(u => u.userId === userId)) {
            selectedUsers.push({
              userId: userId,
              userName: userData.name,
              emailAddress: userData.emailAddress
            });
          }
        } else {
          selectedUsers = selectedUsers.filter(u => u.userId !== userId);
        }
        updateSaveButtonState();
      });

      // Sự kiện ô tìm kiếm
      _$filterInput.on('keyup', function () {
        dataTable.search($(this).val()).draw();
      });

      _modalManager.getModal().find('.add-member-filter-button').click(function () {
        refreshTable();
      });

      // Sự kiện nút Save
      this.save = function () {
        // Bảo đảm rằng các checkbox đang hiển thị cũng được đồng bộ vào selectedUsers
        $('.user-checkbox').each(function () {
          const userId = $(this).data('user-id');
          const row = dataTable.row($(this).closest('tr'));
          const userData = row.data();

          if ($(this).is(':checked')) {
            if (!selectedUsers.some(u => u.userId === userId)) {
              selectedUsers.push({
                userId: userId,
                userName: userData.name,
                emailAddress: userData.emailAddress
              });
            }
          } else {
            selectedUsers = selectedUsers.filter(u => u.userId !== userId);
          }
        });
        console.log(selectedUsers);
        _modalManager.setResult(selectedUsers);

        _modalManager.close();
      };
    };
  };
})();
